// FIREBASE REAL-TIME SYNC INTEGRATION
// ============================================
// Ibi bituma impinduka ziva muri /dereva/admin/category-control.html
// zigera kuri /driving-test.html ako kanya

// Initialize Firebase if not already initialized
(function initializeFirebaseSync() {
    // Check if Firebase is available
    if (typeof firebase === 'undefined') {
        console.log('⏳ Firebase SDK not loaded yet, waiting for driving-test.html to initialize...');
        return;
    }
    
    const FIREBASE_CONFIG = {
        apiKey: "AIzaSyD4VnHyXpCm_1PiKHSjr0JL4XEBade1OwY",
        authDomain: "driving-e8a66.firebaseapp.com",
        databaseURL: "https://driving-e8a66-default-rtdb.firebaseio.com",
        projectId: "driving-e8a66",
        storageBucket: "driving-e8a66.appspot.com",
        messagingSenderId: "629983254477",
        appId: "1:629983254477:web:efe9505af7212013e51684"
    };
    
    let firebaseApp = null;
    let firebaseDatabase = null;
    
    try {
        if (firebase.apps.length === 0) {
            firebaseApp = firebase.initializeApp(FIREBASE_CONFIG, 'questionsSync');
            console.log('✅ Firebase initialized from questions.js');
        } else {
            firebaseApp = firebase.apps[0];
        }
        
        firebaseDatabase = firebase.database();
        
        // ===== LISTEN FOR CATEGORY CHANGES =====
        const categoriesRef = firebaseDatabase.ref('driving_test_sync/categories');
        categoriesRef.on('value', (snapshot) => {
            const remoteCategories = snapshot.val();
            
            if (remoteCategories && Array.isArray(remoteCategories)) {
                console.log('🔄 [questions.js] Received category update from admin panel');
                
                // Create a global event that driving-test.html can listen to
                const categoryUpdateEvent = new CustomEvent('categoriesUpdated', {
                    detail: {
                        categories: remoteCategories,
                        timestamp: Date.now()
                    }
                });
                window.dispatchEvent(categoryUpdateEvent);
                
                // Also store in localStorage for persistence
                localStorage.setItem('lastKnownCategoryConfig', JSON.stringify({
                    categories: remoteCategories,
                    testDuration: 30,
                    passingScore: 75,
                    questionsPerTest: 20,
                    lastSync: new Date().toISOString()
                }));
                
                console.log(`✅ [questions.js] Synced ${remoteCategories.length} categories`);
            }
        });
        
        // ===== LISTEN FOR CONFIG CHANGES =====
        const configRef = firebaseDatabase.ref('driving_test_sync/config');
        configRef.on('value', (snapshot) => {
            const remoteConfig = snapshot.val();
            
            if (remoteConfig) {
                console.log('🔄 [questions.js] Received config update from admin panel');
                
                const configUpdateEvent = new CustomEvent('configUpdated', {
                    detail: remoteConfig
                });
                window.dispatchEvent(configUpdateEvent);
                
                // Update localStorage
                const existingConfig = JSON.parse(localStorage.getItem('lastKnownCategoryConfig') || '{}');
                existingConfig.testDuration = remoteConfig.duration || 30;
                existingConfig.passingScore = remoteConfig.passingScore || 75;
                existingConfig.questionsPerTest = remoteConfig.questionsPerTest || 20;
                existingConfig.lastSync = new Date().toISOString();
                localStorage.setItem('lastKnownCategoryConfig', JSON.stringify(existingConfig));
            }
        });
        
        // ===== LISTEN FOR QUESTION CHANGES =====
        const questionsRef = firebaseDatabase.ref('questions');
        questionsRef.on('value', (snapshot) => {
            if (snapshot.exists()) {
                console.log('🔄 [questions.js] Questions updated from admin panel');
                
                const remoteQuestions = [];
                snapshot.forEach((child) => {
                    const q = child.val();
                    remoteQuestions.push({
                        id: child.key,
                        question: q.question || q.text || '',
                        options: Array.isArray(q.options) ? q.options : ['(a) Igisubizo A', '(b) Igisubizo B', '(c) Igisubizo C', '(d) Igisubizo D'],
                        correctAnswer: q.correctAnswer !== undefined ? q.correctAnswer : 0,
                        image: q.image || null,
                        category: q.category || 'Test 1',
                        categoryId: q.categoryId || null,
                        explanation: q.explanation || '',
                        level: q.level || 'medium',
                        time: q.time || 1.5,
                        enabled: q.enabled !== false
                    });
                });
                
                // Update window.ALL_QUESTIONS if it exists
                if (window.ALL_QUESTIONS) {
                    // Merge with existing questions? Or replace?
                    // For now, we'll just log and let driving-test.html handle it
                    const questionsUpdateEvent = new CustomEvent('questionsUpdated', {
                        detail: {
                            questions: remoteQuestions,
                            count: remoteQuestions.length
                        }
                    });
                    window.dispatchEvent(questionsUpdateEvent);
                    
                    console.log(`✅ [questions.js] ${remoteQuestions.length} questions synced from Firebase`);
                }
            }
        });
        
        console.log('✅ [questions.js] Firebase real-time listeners active');
        console.log('📡 Listening for changes from /dereva/admin/category-control.html');
        
    } catch (error) {
        console.error('❌ [questions.js] Firebase sync initialization failed:', error);
    }
})();

// ============================================
// EXPORT SYNC FUNCTIONS FOR ADMIN USE
// ============================================

/**
 * Force refresh questions from Firebase
 * Iyi function ishobora guhamagarwa na driving-test.html
 * kugirango ivugurure ibibazo ibyo yanditse mu mutwe
 */
window.refreshQuestionsFromFirebase = async function() {
    console.log('🔄 Manually refreshing questions from Firebase...');
    
    if (typeof firebase === 'undefined' || !firebase.database) {
        console.error('❌ Firebase not available');
        return false;
    }
    
    try {
        const database = firebase.database();
        const snapshot = await database.ref('questions').once('value');
        
        if (snapshot.exists()) {
            const remoteQuestions = [];
            snapshot.forEach((child) => {
                const q = child.val();
                remoteQuestions.push({
                    id: child.key,
                    question: q.question || q.text || '',
                    options: Array.isArray(q.options) ? q.options : ['(a) Igisubizo A', '(b) Igisubizo B', '(c) Igisubizo C', '(d) Igisubizo D'],
                    correctAnswer: q.correctAnswer !== undefined ? q.correctAnswer : 0,
                    image: q.image || null,
                    category: q.category || 'Test 1',
                    categoryId: q.categoryId || null,
                    explanation: q.explanation || '',
                    level: q.level || 'medium',
                    time: q.time || 1.5,
                    enabled: q.enabled !== false
                });
            });
            
            // Update ALL_QUESTIONS
            if (window.ALL_QUESTIONS) {
                // Merge: replace questions that exist in Firebase, keep others
                const firebaseQuestionIds = new Set(remoteQuestions.map(q => q.id));
                
                // Keep local questions not in Firebase
                const localQuestions = window.ALL_QUESTIONS.filter(q => !firebaseQuestionIds.has(q.id));
                
                // Combine
                window.ALL_QUESTIONS = [...localQuestions, ...remoteQuestions];
                
                // Sort by ID or category
                window.ALL_QUESTIONS.sort((a, b) => {
                    if (a.category === b.category) {
                        return (a.questionNumber || 0) - (b.questionNumber || 0);
                    }
                    return (a.category || '').localeCompare(b.category || '');
                });
                
                console.log(`✅ Merged ${remoteQuestions.length} Firebase questions with ${localQuestions.length} local questions`);
                console.log(`📊 Total questions: ${window.ALL_QUESTIONS.length}`);
                
                // Dispatch event
                const questionsUpdateEvent = new CustomEvent('questionsRefreshed', {
                    detail: {
                        questions: window.ALL_QUESTIONS,
                        count: window.ALL_QUESTIONS.length,
                        firebaseCount: remoteQuestions.length
                    }
                });
                window.dispatchEvent(questionsUpdateEvent);
                
                return {
                    success: true,
                    total: window.ALL_QUESTIONS.length,
                    firebaseQuestions: remoteQuestions.length,
                    localQuestions: localQuestions.length
                };
            }
        }
        
        return { success: false, message: 'No questions found in Firebase' };
        
    } catch (error) {
        console.error('❌ Failed to refresh questions:', error);
        return { success: false, error: error.message };
    }
};

// ============================================
// DRIVING-TEST.HTML COMPATIBILITY LAYER
// ============================================

// Ensure driving-test.html can access these functions
if (typeof window.drivingTestHelpers === 'undefined') {
    window.drivingTestHelpers = {
        refreshQuestions: window.refreshQuestionsFromFirebase,
        getCategories: function() {
            const savedConfig = localStorage.getItem('lastKnownCategoryConfig');
            if (savedConfig) {
                try {
                    return JSON.parse(savedConfig).categories || [];
                } catch (e) {
                    return [];
                }
            }
            return [];
        },
        getConfig: function() {
            const savedConfig = localStorage.getItem('lastKnownCategoryConfig');
            if (savedConfig) {
                try {
                    const config = JSON.parse(savedConfig);
                    return {
                        duration: config.testDuration || 30,
                        passingScore: config.passingScore || 75,
                        questionsPerTest: config.questionsPerTest || 20
                    };
                } catch (e) {
                    return { duration: 30, passingScore: 75, questionsPerTest: 20 };
                }
            }
            return { duration: 30, passingScore: 75, questionsPerTest: 20 };
        }
    };
}

