if (window.ALL_QUESTIONS) {
    console.log(`📊 FINAL VERIFICATION: ${window.ALL_QUESTIONS.length} questions available`);
    if (window.ALL_QUESTIONS.length !== 440) {
        console.warn(`⚠️ Expected 440 questions, but found ${window.ALL_QUESTIONS.length}`);
        console.warn('   This is normal if you are using custom questions from Firebase');
    }
}

