console.log('✅ [questions.js] Real-time sync footer installed successfully!');
console.log('📡 This file will now automatically reflect changes from category-control.html');
console.log('🔗 Firebase path: driving_test_sync/categories');
console.log('🔗 Firebase path: driving_test_sync/config');
console.log('🔗 Firebase path: questions');

